@include('user.partials.overview-styles')
<style>
.bk-page{width:100%;max-width:none;color:var(--text-primary)}.bk-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:20px}.bk-panel{border:1px solid var(--border-glass);background:var(--bg-card);border-radius:22px;padding:24px;min-width:0}.bk-panel h2{font-size:18px;font-weight:700;margin-bottom:8px}.bk-muted{font-size:13px;color:var(--text-muted);line-height:1.6}.bk-actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.bk-label{display:block;font-size:13px;font-weight:600;margin-bottom:7px}.bk-input{width:100%;padding:11px 13px;border-radius:12px;border:1px solid var(--border-glass);background:var(--bg-glass-input);color:var(--text-primary);font:inherit;min-width:0}.bk-editor-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(300px,1fr);gap:24px;align-items:start}.bk-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.bk-field{margin-bottom:18px}.bk-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.bk-tabs button{padding:10px 18px;border-radius:12px;border:1px solid var(--border-glass)}.bk-tabs button[aria-selected=true]{background:var(--accent,#3454ef);color:#fff;border-color:transparent}.bk-preview{position:sticky;top:100px}.bk-swatch{width:32px;height:32px;border-radius:50%;border:1px solid rgba(0,0,0,.08)}.bk-check{display:flex;gap:10px;align-items:center;padding:12px;border:1px solid var(--border-glass);border-radius:12px;margin:8px 0}.bk-feedback{padding:12px;border-radius:12px;background:var(--bg-glass-hover);margin:12px 0}.bk-stat-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin:24px 0}.bk-stat-grid .ov-count-art{right:12px}html .bk-stat-grid .ov-count-label,html .bk-stat-grid .ov-count strong{color:#fff!important}html .bk-stat-grid .ov-count-bottom p{color:rgba(255,255,255,.85)!important}.bk-compact{font-size:12px!important;min-height:0!important}.bk-editor-grid :focus-visible{outline:2px solid var(--accent,#3454ef);outline-offset:2px}
@media(max-width:1000px){.bk-editor-grid{grid-template-columns:1fr}.bk-preview{position:static}}@media(max-width:600px){.bk-form-grid,.bk-stat-grid{grid-template-columns:1fr}.bk-panel{padding:18px}}
.bk-disclosure{border-bottom:1px solid var(--border-glass);padding:14px 0}.bk-disclosure summary{cursor:pointer;font-weight:600;font-size:14px}.bk-library-card{overflow:visible;position:relative}.bk-cover{overflow:hidden;position:relative;min-height:150px;margin:-24px -24px 24px;padding:22px 24px;border-radius:22px 22px 0 0;background:linear-gradient(125deg,#101c33,var(--brand-color));color:#fff;display:flex;flex-direction:column;gap:8px}.bk-cover strong{font-size:24px;line-height:1.2;position:relative;z-index:1;max-width:85%}.bk-cover>span{font-size:12px;opacity:.88;position:relative;z-index:1}.bk-cover .bk-cover-caption{font-size:10px;letter-spacing:2px}.bk-cover-orbit{position:absolute;right:-35px;top:15px;width:150px;height:150px;border:30px solid #ffffff18;border-radius:50%}.bk-type-sample{font-size:32px;font-weight:700;margin:16px 0}.bk-type-sample span{font-size:12px;font-weight:400;color:var(--text-muted);margin-left:10px}.bk-card-menu{position:relative}.bk-card-menu summary{cursor:pointer;list-style:none}.bk-menu-content{position:absolute;bottom:48px;right:0;min-width:190px;z-index:10;display:grid;gap:7px;padding:12px;border:1px solid var(--border-glass);border-radius:16px;background:var(--bg-dropdown);box-shadow:0 12px 35px #0b163333}.bk-menu-content form button,.bk-menu-content>a{width:100%;text-align:left;display:block}.bk-asset-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}@media(max-width:600px){.bk-cover{margin:-18px -18px 18px}.bk-asset-grid{grid-template-columns:1fr}}
.bk-phone-stage{height:650px;overflow:hidden;border:8px solid #172033;border-radius:30px;background:#fff;max-width:100%;position:relative}.bk-phone-stage iframe{border:0;transform-origin:top left;display:block}.bk-preview [aria-pressed=true]{background:var(--accent,#3454ef);color:#fff}
</style>
<style>
.bk-phone-stage{width:390px;max-width:100%;height:740px;margin:24px auto 12px;border:10px solid #08090d;border-radius:48px;background:#fff;box-shadow:0 0 0 2px #393b43,0 24px 55px #0f172a30;isolation:isolate}.bk-phone-stage:after{content:'';position:absolute;top:0;left:50%;transform:translateX(-50%);width:112px;height:25px;background:#08090d;border-radius:0 0 18px 18px;pointer-events:none;z-index:5}.bk-icon-scene{padding:18px;border:1px solid var(--border-glass);border-radius:16px;margin:12px 0;background:#f8fafc;color:#172033}.bk-icon-scene.dark{background:#172033;color:#f8fafc}.bk-icon-scene img{width:32px;height:32px;object-fit:contain;display:inline-block;margin-right:10px}.bk-icon-home{display:flex;align-items:center;gap:18px;padding:22px;background:linear-gradient(135deg,#818cf8,#c084fc);border-radius:18px}.bk-icon-home img{width:64px;height:64px;border-radius:15px;background:white;padding:8px}.bk-preset-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
</style>
